BULLES_LOAD({"ep":"sophie/17","part":"text","paras":[{"poem":false,"s":[{"fr":"Sophie et Paul se promenaient un jour avec leur bonne ; ils revenaient de chez une pauvre femme à laquelle ils avaient été porter de l’argent.","en":"One day Sophie and Paul were out walking with their nanny; they were coming back from a poor woman's house, where they had taken her some money.","pt":"Um dia, a Sophie e o Paul passeavam com a ama; voltavam de casa de uma pobre mulher a quem tinham ido levar dinheiro.","es":"Un día Sophie y Paul paseaban con su niñera; volvían de casa de una mujer pobre a la que habían ido a llevar dinero."},{"fr":"Ils revenaient tout doucement ; tantôt ils cherchaient à grimper à un arbre, tantôt ils passaient au travers des haies et se cachaient dans les buissons.","en":"They were walking back very slowly; now they tried to climb a tree, now they went through hedges and hid in the bushes.","pt":"Voltavam devagarinho; ora tentavam subir a uma árvore, ora passavam através das sebes e se escondiam nos arbustos.","es":"Volvían muy despacio; unas veces intentaban trepar a un árbol, otras pasaban a través de los setos y se escondían en los matorrales."},{"fr":"Sophie était cachée et Paul la cherchait, lorsqu’elle entendit un tout petit miaou bien faible, bien plaintif.","en":"Sophie was hiding and Paul was looking for her when she heard a tiny miaow, very weak and very pitiful.","pt":"A Sophie estava escondida e o Paul procurava-a quando ela ouviu um miau pequenino, muito fraco, muito lastimoso.","es":"Sophie estaba escondida y Paul la buscaba, cuando oyó un maullido muy pequeñito, muy débil y muy lastimero."},{"fr":"Sophie eut peur ; elle sortit de sa cachette.","en":"Sophie was frightened; she came out of her hiding place.","pt":"A Sophie teve medo; saiu do esconderijo.","es":"Sophie se asustó; salió de su escondite."}]},{"poem":false,"s":[{"fr":"« Paul, dit-elle, appelons ma bonne ; j’ai entendu un petit cri, comme un chat qui miaule, tout près de moi, dans le buisson.","en":"\"Paul,\" she said, \"let's call Nanny; I heard a little cry, like a cat miaowing, right next to me in the bush.","pt":"— Paul — disse ela —, vamos chamar a ama; ouvi um gritinho, como um gato a miar, mesmo ao pé de mim, no arbusto.","es":"«Paul», dijo, «llamemos a la niñera; he oído un gritito, como un gato que maúlla, muy cerca de mí, en el matorral."}]},{"poem":false,"s":[{"fr":"Pourquoi faut-il appeler ta bonne pour cela ?","en":"Why do we need to call your nanny for that?","pt":"Para que é preciso chamar a tua ama por causa disso?","es":"¿Y para eso hay que llamar a tu niñera?"},{"fr":"Allons voir nous-mêmes ce que c’est.","en":"Let's go and see for ourselves what it is.","pt":"Vamos nós ver o que é.","es":"Vamos a ver nosotros mismos qué es."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Oh non ! j’ai peur.","en":"Oh no! I'm scared.","pt":"Oh, não! Tenho medo.","es":"¡Oh, no! Tengo miedo."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Peur ! et de quoi ?","en":"Scared! Of what?","pt":"Medo! E de quê?","es":"¡Miedo! ¿Y de qué?"},{"fr":"Tu dis toi-même que c’était un petit cri.","en":"You said yourself it was a little cry.","pt":"Tu própria dizes que era um gritinho.","es":"Tú misma dices que era un gritito."},{"fr":"Ce n’est donc pas une grosse bête.","en":"So it isn't a big animal.","pt":"Então não é um bicho grande.","es":"Así que no es un bicho grande."}],"who":{"fr":"Paul, riant","en":"Paul, laughing","pt":"Paul, a rir","es":"Paul, riendo"}},{"poem":false,"s":[{"fr":"Je ne sais pas ; c’est peut-être un serpent, un jeune loup.","en":"I don't know; maybe it's a snake, or a young wolf.","pt":"Não sei; se calhar é uma cobra, um lobo pequeno.","es":"No sé; a lo mejor es una serpiente, o un lobo pequeño."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Ha ! ha ! ha !","en":"Ha! ha! ha!","pt":"Ah! ah! ah!","es":"¡Ja, ja, ja!"},{"fr":"Un serpent qui crie !","en":"A snake that cries!","pt":"Uma cobra que grita!","es":"¡Una serpiente que grita!"},{"fr":"C’est nouveau, cela !","en":"That's a new one!","pt":"Essa é nova!","es":"¡Eso sí que es nuevo!"},{"fr":"Et un jeune loup qui pousse un si petit cri, que moi, qui étais tout près de toi, je ne l’ai pas entendu !","en":"And a young wolf that gives such a little cry that I, who was right next to you, didn't even hear it!","pt":"E um lobo pequeno que dá um grito tão pequenino que eu, que estava mesmo ao pé de ti, nem o ouvi!","es":"¡Y un lobo pequeño que da un grito tan chiquitito que yo, que estaba muy cerca de ti, no lo he oído!"}],"who":{"fr":"Paul, riant","en":"Paul, laughing","pt":"Paul, a rir","es":"Paul, riendo"}},{"poem":false,"s":[{"fr":"Voilà le même cri !","en":"There's the same cry!","pt":"Lá está o mesmo grito!","es":"¡Otra vez el mismo grito!"},{"fr":"Entends-tu ? »","en":"Do you hear it?\"","pt":"Estás a ouvir?","es":"¿Lo oyes?»."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Paul écouta et entendit en effet un petit miaou bien faible qui sortait du buisson.","en":"Paul listened and did indeed hear a very weak little miaow coming from the bush.","pt":"O Paul pôs-se à escuta e ouviu de facto um miau pequenino e muito fraco que saía do arbusto.","es":"Paul escuchó y oyó, en efecto, un maullido muy débil que salía del matorral."},{"fr":"Il y courut malgré les prières de Sophie.","en":"He ran over in spite of Sophie's pleading.","pt":"Correu para lá apesar das súplicas da Sophie.","es":"Corrió hacia allí a pesar de los ruegos de Sophie."}]},{"poem":false,"s":[{"fr":"« C’est un pauvre petit chat qui a l’air malade, s’écria-t-il après avoir cherché quelques instants.","en":"\"It's a poor little kitten that looks ill,\" he cried after searching for a few moments.","pt":"— É um pobre gatinho que parece doente — exclamou ele depois de procurar uns instantes.","es":"«Es un pobre gatito que parece enfermo», exclamó después de buscar unos instantes."},{"fr":"Viens voir comme il paraît misérable. »","en":"\"Come and see how miserable it looks.\"","pt":"— Anda ver como parece infeliz.","es":"«Ven a ver qué aspecto tan miserable tiene»."}]},{"poem":false,"s":[{"fr":"Sophie accourut ; elle vit un tout petit chat tout blanc, mouillé de rosée et taché de boue, qui était étendu tout près de la place où elle s’était cachée.","en":"Sophie ran up; she saw a tiny, all-white kitten, wet with dew and spotted with mud, lying very close to where she had been hiding.","pt":"A Sophie acorreu; viu um gatinho pequenino, todo branco, molhado de orvalho e sujo de lama, que estava estendido mesmo ao pé do sítio onde ela se tinha escondido.","es":"Sophie acudió corriendo; vio un gatito muy pequeño, todo blanco, mojado de rocío y manchado de barro, que estaba tumbado muy cerca del sitio donde ella se había escondido."}]},{"poem":false,"s":[{"fr":"« Il faut appeler ma bonne, dit Sophie, pour qu’elle l’emporte ; pauvre petit, comme il tremble.","en":"\"We must call Nanny,\" said Sophie, \"so she can carry it; poor little thing, how it's shivering.\"","pt":"— Temos de chamar a ama — disse a Sophie — para ela o levar; coitadinho, como treme.","es":"«Hay que llamar a la niñera», dijo Sophie, «para que se lo lleve; pobrecito, cómo tiembla."}]},{"poem":false,"s":[{"fr":"— Et comme il est maigre ! » dit Paul.","en":"\"And how thin it is!\" said Paul.","pt":"— E como é magro! — disse o Paul.","es":"—¡Y qué flaco está!», dijo Paul."}]},{"poem":false,"s":[{"fr":"Ils appelèrent la bonne, qui les suivait de loin.","en":"They called the nanny, who was following them some way behind.","pt":"Chamaram a ama, que os seguia de longe.","es":"Llamaron a la niñera, que los seguía de lejos."},{"fr":"Quand elle les rejoignit, ils lui montrèrent le petit chat et lui demandèrent de l’emporter.","en":"When she caught up with them, they showed her the kitten and asked her to carry it.","pt":"Quando ela os alcançou, mostraram-lhe o gatinho e pediram-lhe que o levasse.","es":"Cuando los alcanzó, le enseñaron el gatito y le pidieron que se lo llevara."}]},{"poem":false,"s":[{"fr":"Mais comment faire pour l’emporter ?","en":"But how am I to carry it?","pt":"Mas como é que o hei de levar?","es":"Pero ¿cómo voy a llevármelo?"},{"fr":"Le pauvre petit malheureux est si mouillé et si sale que je ne peux pas le prendre dans mes mains.","en":"The poor little wretch is so wet and so dirty that I can't pick it up in my hands.","pt":"O pobre desgraçadinho está tão molhado e tão sujo que não lhe posso pegar com as mãos.","es":"El pobre desgraciado está tan mojado y tan sucio que no puedo cogerlo con las manos."}],"who":{"fr":"La bonne","en":"the maid","pt":"a criada","es":"La niñera"}},{"poem":false,"s":[{"fr":"Eh bien, ma bonne, mettez-le dans des feuilles.","en":"Well, Nanny, put it in some leaves.","pt":"Então, ama, ponha-o em cima de umas folhas.","es":"Pues, niñera, póngalo en unas hojas."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Ou plutôt dans mon mouchoir ; il sera bien mieux.","en":"Or better, in my handkerchief; it will be much more comfortable.","pt":"Ou antes no meu lenço; fica muito melhor.","es":"O mejor en mi pañuelo; estará mucho mejor."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"C’est cela !","en":"That's it!","pt":"Isso mesmo!","es":"¡Eso es!"},{"fr":"Essuyons-le avec mon mouchoir, et couchons-le dans le tien ; ma bonne l’emportera.","en":"Let's dry it with my handkerchief and lay it in yours; Nanny will carry it.","pt":"Vamos secá-lo com o meu lenço e deitá-lo no teu; a ama leva-o.","es":"Sequémoslo con mi pañuelo y acostémoslo en el tuyo; la niñera se lo llevará."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"La bonne les aida à arranger le petit chat, qui n’avait pas la force de remuer ;","en":"The nanny helped them settle the kitten, which didn't have the strength to move;","pt":"A ama ajudou-os a arranjar o gatinho, que não tinha forças para se mexer;","es":"La niñera les ayudó a arreglar al gatito, que no tenía fuerzas para moverse;"},{"fr":"quand il fut bien enveloppé dans le mouchoir, la bonne le prit, et tous se dépêchèrent d’arriver à la maison pour lui donner du lait chaud.","en":"when it was well wrapped in the handkerchief, the nanny picked it up, and they all hurried home to give it some warm milk.","pt":"quando ficou bem embrulhado no lenço, a ama pegou nele, e todos se apressaram a chegar a casa para lhe dar leite quente.","es":"cuando estuvo bien envuelto en el pañuelo, la niñera lo cogió, y todos se dieron prisa en llegar a casa para darle leche caliente."}]},{"poem":false,"s":[{"fr":"Ils n’étaient pas loin de la maison, et ils furent bientôt arrivés.","en":"They weren't far from the house, and they were soon there.","pt":"Não estavam longe de casa e depressa chegaram.","es":"No estaban lejos de la casa, y pronto llegaron."},{"fr":"Sophie et Paul coururent en avant, à la cuisine.","en":"Sophie and Paul ran ahead to the kitchen.","pt":"A Sophie e o Paul correram à frente para a cozinha.","es":"Sophie y Paul corrieron delante, a la cocina."}]},{"poem":false,"s":[{"fr":"« Donnez-nous bien vite une tasse de lait chaud, dit Sophie à Jean, le cuisinier.","en":"\"Quick, give us a cup of warm milk,\" Sophie said to Jean, the cook.","pt":"— Dê-nos depressa uma chávena de leite quente — disse a Sophie ao Jean, o cozinheiro.","es":"«Denos deprisa una taza de leche caliente», le dijo Sophie a Jean, el cocinero."}]},{"poem":false,"s":[{"fr":"— Pour quoi faire, mademoiselle ? répondit Jean.","en":"\"What for, miss?\" answered Jean.","pt":"— Para quê, menina? — respondeu o Jean.","es":"«¿Para qué, señorita?», respondió Jean."}]},{"poem":false,"s":[{"fr":"— Pour un pauvre petit chat que nous avons trouvé dans une haie et qui est presque mort de faim.","en":"\"For a poor little kitten we found in a hedge, which is nearly starving to death.","pt":"— Para um pobre gatinho que encontrámos numa sebe e que está quase a morrer de fome.","es":"«Para un pobre gatito que hemos encontrado en un seto y que está casi muerto de hambre."},{"fr":"Le voici ; ma bonne l’apporte dans un mouchoir. »","en":"Here it is; Nanny is bringing it in a handkerchief.\"","pt":"Aqui está ele; a ama tra-lo num lenço.","es":"Aquí está; la niñera lo trae en un pañuelo»."}]},{"poem":false,"s":[{"fr":"La bonne posa le mouchoir par terre ; le cuisinier apporta une assiettée de lait chaud au petit chat, qui se jeta dessus et avala tout sans en laisser une goutte.","en":"The nanny put the handkerchief on the floor; the cook brought a plateful of warm milk for the kitten, which threw itself on it and swallowed it all without leaving a drop.","pt":"A ama pousou o lenço no chão; o cozinheiro trouxe um prato de leite quente para o gatinho, que se atirou a ele e engoliu tudo sem deixar uma gota.","es":"La niñera dejó el pañuelo en el suelo; el cocinero le trajo un plato de leche caliente al gatito, que se lanzó encima y se lo bebió todo sin dejar ni una gota."}]},{"poem":false,"s":[{"fr":"« J’espère que le voilà content, dit la bonne.","en":"\"I hope it's happy now,\" said the nanny.","pt":"— Espero que agora esteja contente — disse a ama.","es":"«Espero que ya esté contento», dijo la niñera."},{"fr":"Il a bu plus de deux verres de lait.","en":"\"It's drunk more than two glasses of milk.","pt":"— Bebeu mais de dois copos de leite.","es":"«Se ha bebido más de dos vasos de leche."}]},{"poem":false,"s":[{"fr":"Ah ! le voilà qui se relève !","en":"Oh! It's getting up!","pt":"Ah! Está a levantar-se!","es":"¡Ah, ya se levanta!"},{"fr":"Il lèche ses poils.","en":"It's licking its fur.","pt":"Está a lamber o pelo.","es":"Se está lamiendo el pelo."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Si nous l’emportions dans notre chambre ?","en":"What if we took it to our room?","pt":"E se o levássemos para o nosso quarto?","es":"¿Y si nos lo lleváramos a nuestro cuarto?"}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Moi, monsieur et mademoiselle, je vous conseillerais de le laisser dans la cuisine, d’abord parce qu’il se séchera mieux dans la cendre chaude, ensuite parce qu’il aura à manger ici tant qu’il voudra ;","en":"If I were you, sir and miss, I'd leave it in the kitchen, first because it will dry better in the warm ashes, then because it will have as much to eat here as it likes;","pt":"Eu, menino e menina, aconselhava-vos a deixá-lo na cozinha, primeiro porque vai secar melhor na cinza quente, depois porque aqui vai ter de comer tanto quanto quiser;","es":"Yo, señor y señorita, les aconsejaría dejarlo en la cocina, primero porque se secará mejor en la ceniza caliente, y además porque aquí tendrá de comer todo lo que quiera;"},{"fr":"enfin parce qu’il pourra sortir quand il en aura besoin, et qu’il apprendra ainsi à être propre.","en":"and finally because it can go out when it needs to, and so it will learn to be clean.","pt":"enfim, porque vai poder sair quando precisar, e assim aprende a ser asseado.","es":"y por último porque podrá salir cuando lo necesite, y así aprenderá a ser limpio."}],"who":{"fr":"Le cuisinier","en":"The cook","pt":"O cozinheiro","es":"El cocinero"}},{"poem":false,"s":[{"fr":"C’est vrai.","en":"That's true.","pt":"É verdade.","es":"Es verdad."},{"fr":"Laissons-le à la cuisine, Sophie.","en":"Let's leave it in the kitchen, Sophie.","pt":"Vamos deixá-lo na cozinha, Sophie.","es":"Dejémoslo en la cocina, Sophie."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Mais il sera toujours à nous et je le verrai tant que je voudrai ?","en":"But it will still be ours, and I can see it as much as I like?","pt":"Mas vai ser sempre nosso, e vou vê-lo sempre que quiser?","es":"Pero ¿seguirá siendo nuestro y podré verlo todo lo que quiera?"}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Certainement, mademoiselle, vous le verrez quand vous voudrez.","en":"Certainly, miss, you'll see it whenever you like.","pt":"Com certeza, menina, vai vê-lo sempre que quiser.","es":"Claro que sí, señorita, lo verá cuando quiera."},{"fr":"Ne sera-t-il pas à vous tout de même ? »","en":"Won't it be yours all the same?\"","pt":"Não vai ser seu na mesma?","es":"¿Acaso no seguirá siendo suyo?»."}],"who":{"fr":"Le cuisinier","en":"The cook","pt":"O cozinheiro","es":"El cocinero"}},{"poem":false,"s":[{"fr":"Il prit le chat, et le posa sur de la cendre chaude, sous le fourneau.","en":"He picked up the cat and put it on some warm ashes under the stove.","pt":"Pegou no gato e pousou-o em cinza quente, debaixo do fogão.","es":"Cogió al gato y lo puso sobre la ceniza caliente, debajo del fogón."},{"fr":"Les enfants le laissèrent dormir et recommandèrent bien au cuisinier de lui mettre du lait près de lui pour qu’il pût en boire toutes les fois qu’il aurait faim.","en":"The children let it sleep and made the cook promise to put some milk beside it so it could drink whenever it was hungry.","pt":"As crianças deixaram-no dormir e recomendaram muito ao cozinheiro que lhe pusesse leite ao pé, para ele poder beber sempre que tivesse fome.","es":"Los niños lo dejaron dormir y le recomendaron mucho al cocinero que le pusiera leche al lado para que pudiera beber cada vez que tuviera hambre."}]},{"poem":false,"s":[{"fr":"Comment appellerons-nous notre chat ?","en":"What shall we call our cat?","pt":"Como vamos chamar ao nosso gato?","es":"¿Cómo vamos a llamar a nuestro gato?"}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Appelons-le Chéri.","en":"Let's call him Darling.","pt":"Vamos chamar-lhe Querido.","es":"Llamémoslo Querido."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Oh non !","en":"Oh no!","pt":"Oh, não!","es":"¡Oh, no!"},{"fr":"C’est commun.","en":"That's ordinary.","pt":"Isso é vulgar.","es":"Es muy corriente."},{"fr":"Appelons-le plutôt Charmant.","en":"Let's call him Charming instead.","pt":"Vamos antes chamar-lhe Encantador.","es":"Llamémoslo mejor Encantador."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Et si en grandissant il devient laid ?","en":"And what if he grows up ugly?","pt":"E se, ao crescer, ficar feio?","es":"¿Y si al crecer se vuelve feo?"}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"C’est vrai.","en":"That's true.","pt":"É verdade.","es":"Es verdad."},{"fr":"Comment l’appeler alors ?","en":"Then what shall we call him?","pt":"Então como lhe vamos chamar?","es":"Entonces, ¿cómo lo llamamos?"},{"fr":"Il faut bien pourtant qu’il ait un nom.","en":"He has to have a name, though.","pt":"Tem de ter um nome, ao fim e ao cabo.","es":"Pero tiene que tener un nombre."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Sais-tu ce qui serait un très joli nom ?","en":"Do you know what would be a really pretty name?","pt":"Sabes o que era um nome muito bonito?","es":"¿Sabes qué nombre sería muy bonito?"},{"fr":"Beau-Minon.","en":"Beau-Minon.","pt":"Beau-Minon.","es":"Bello Minino."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Ah oui !","en":"Oh yes!","pt":"Ah, sim!","es":"¡Ah, sí!"},{"fr":"Comme dans le conte de Blondine.","en":"Like in the story of Blondine.","pt":"Como no conto da Blondine.","es":"Como en el cuento de Blondine."},{"fr":"C’est vrai : appelons-le Beau-Minon.","en":"That's right: let's call him Beau-Minon.","pt":"É verdade: vamos chamar-lhe Beau-Minon.","es":"Es verdad: llamémoslo Bello Minino."},{"fr":"Je demanderai à maman de lui faire un petit collier et de broder tout autour Beau-Minon. »","en":"I'll ask Mama to make him a little collar and embroider Beau-Minon all round it.\"","pt":"Vou pedir à mamã que lhe faça uma coleirinha e borde à volta Beau-Minon.","es":"Le pediré a mamá que le haga un collarcito y que borde alrededor «Bello Minino»»."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Et les enfants coururent chez Mme de Réan pour lui raconter l’histoire du petit chat et pour lui demander un collier.","en":"And the children ran to Madame de Réan to tell her the story of the kitten and ask her for a collar.","pt":"E as crianças correram aos aposentos da senhora de Réan para lhe contar a história do gatinho e lhe pedir uma coleira.","es":"Y los niños corrieron al cuarto de la señora de Réan para contarle la historia del gatito y pedirle un collar."},{"fr":"La maman alla voir le chat et prit la mesure de son cou.","en":"Her mother went to see the cat and measured its neck.","pt":"A mãe foi ver o gato e tirou a medida do pescoço dele.","es":"La mamá fue a ver al gato y le tomó la medida del cuello."}]},{"poem":false,"s":[{"fr":"« Je ne sais pas si ce pauvre chat pourra vivre, dit-elle, il est si maigre et si faible qu’il peut à peine se tenir sur ses pattes.","en":"\"I don't know whether this poor cat will live,\" she said; \"it's so thin and so weak that it can hardly stand on its legs.","pt":"— Não sei se este pobre gato vai conseguir viver — disse ela —; está tão magro e tão fraco que mal se aguenta nas patas.","es":"«No sé si este pobre gato podrá vivir», dijo; «está tan flaco y tan débil que apenas se tiene en pie."}]},{"poem":false,"s":[{"fr":"Mais comment s’est-il trouvé dans la haie ?","en":"But how did it end up in the hedge?","pt":"Mas como é que foi parar à sebe?","es":"Pero ¿cómo ha ido a parar al seto?"},{"fr":"Les chats ne vivent pas dans les bois.","en":"Cats don't live in the woods.","pt":"Os gatos não vivem nos bosques.","es":"Los gatos no viven en el bosque."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Ce sont peut-être de méchants enfants qui l’ont emporté pour jouer, et l’auront jeté ensuite dans la haie, pensant qu’il pourrait revenir dans sa maison tout seul.","en":"Perhaps some nasty children took it away to play with and then threw it into the hedge, thinking it could find its own way home.","pt":"Talvez tenham sido uns miúdos maus que o levaram para brincar e o tenham depois atirado para a sebe, pensando que ele podia voltar sozinho para casa.","es":"Quizá unos niños malos se lo llevaron para jugar y luego lo tiraron al seto, pensando que podría volver solo a su casa."}],"who":{"fr":"Madame de réan","en":"Madame de Réan","pt":"a senhora de Réan","es":"La señora de Réan"}},{"poem":false,"s":[{"fr":"Pourquoi aussi n’est-il pas revenu ?","en":"Then why didn't it come back?","pt":"Então porque é que ele não voltou?","es":"¿Y por qué no ha vuelto?"},{"fr":"C’est bien sa faute s’il a été malheureux.","en":"It's its own fault if it was unhappy.","pt":"A culpa é dele se foi infeliz.","es":"Es culpa suya si lo ha pasado mal."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Il est trop jeune pour avoir pu retrouver son chemin ; et puis, il vient peut-être de très loin.","en":"It's too young to have found its way back; and besides, it may have come from very far away.","pt":"É novo demais para ter encontrado o caminho; e depois, talvez venha de muito longe.","es":"Es demasiado pequeño para haber encontrado el camino; y además, quizá venga de muy lejos."},{"fr":"Si de méchants hommes t’emmenaient très loin et te laissaient au coin d’un bois, que ferais-tu ?","en":"If wicked men took you very far away and left you at the edge of a wood, what would you do?","pt":"Se uns homens maus te levassem para muito longe e te deixassem à beira de um bosque, o que fazias?","es":"Si unos hombres malos te llevaran muy lejos y te dejaran en la linde de un bosque, ¿qué harías?"},{"fr":"Crois-tu que tu pourrais retrouver ton chemin toute seule ?","en":"Do you think you could find your way back all by yourself?","pt":"Achas que conseguias encontrar o caminho sozinha?","es":"¿Crees que podrías encontrar el camino tú sola?"}],"who":{"fr":"Madame de réan","en":"Madame de Réan","pt":"a senhora de Réan","es":"La señora de Réan"}},{"poem":false,"s":[{"fr":"Oh ! je ne serais pas embarrassée !","en":"Oh, I wouldn't be at a loss!","pt":"Oh! Não ficava atrapalhada!","es":"¡Oh, no tendría ningún problema!"},{"fr":"Je marcherais toujours jusqu’à ce que je rencontre quelqu’un ou que je voie une maison ; alors je dirais comment je m’appelle et je demanderais qu’on me ramenât.","en":"I'd keep walking until I met someone or saw a house; then I'd say what my name was and ask them to take me home.","pt":"Andava sempre até encontrar alguém ou ver uma casa; então dizia como me chamava e pedia que me levassem para casa.","es":"Andaría y andaría hasta encontrarme con alguien o ver una casa; entonces diría cómo me llamo y pediría que me llevaran a casa."}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"D’abord, tu rencontrerais peut-être de méchantes gens qui ne voudraient pas se déranger de leur chemin ou de leur ouvrage pour te ramener.","en":"First of all, you might meet unkind people who wouldn't want to go out of their way or leave their work to take you home.","pt":"Primeiro, talvez encontrasses gente má que não quisesse desviar-se do seu caminho nem deixar o seu trabalho para te levar.","es":"Para empezar, quizá te encontraras con gente mala que no quisiera apartarse de su camino ni dejar su trabajo para llevarte."},{"fr":"Et puis, toi, tu peux parler, on te comprendrait !","en":"And besides, you can talk; people would understand you!","pt":"E depois, tu sabes falar, compreendiam-te!","es":"Y además, tú puedes hablar, ¡te entenderían!"},{"fr":"Mais le pauvre chat, crois-tu que, s’il était entré dans une maison, on aurait compris ce qu’il voulait, où il demeurait ?","en":"But the poor cat: do you think that if it had gone into a house, anyone would have understood what it wanted or where it lived?","pt":"Mas o pobre gato, achas que, se tivesse entrado numa casa, alguém tinha percebido o que ele queria e onde morava?","es":"Pero el pobre gato, ¿crees que, si hubiera entrado en una casa, habrían entendido lo que quería, dónde vivía?"},{"fr":"On l’aurait chassé, battu, tué peut-être.","en":"They would have chased it away, beaten it, perhaps killed it.","pt":"Tinham-no enxotado, batido, talvez matado.","es":"Lo habrían echado, le habrían pegado, quizá lo habrían matado."}],"who":{"fr":"La maman","en":"Mother","pt":"a mãe","es":"Mamá"}},{"poem":false,"s":[{"fr":"Mais pourquoi a-t-il été dans ce buisson pour y mourir de faim ?","en":"But why did it go into that bush to starve to death?","pt":"Mas porque é que ele foi para aquele arbusto morrer de fome?","es":"Pero ¿por qué se metió en ese matorral a morirse de hambre?"}],"who":{"fr":"Sophie","en":"Sophie","pt":"Sophie","es":"Sophie"}},{"poem":false,"s":[{"fr":"Les mauvais garçons l’ont peut-être jeté là après l’avoir battu.","en":"Perhaps the bad boys threw it there after beating it.","pt":"Talvez os rapazes maus o tenham atirado para lá depois de lhe baterem.","es":"A lo mejor los chicos malos lo tiraron allí después de pegarle."},{"fr":"D’ailleurs il n’a pas été si bête d’être resté là, puisque vous avez passé auprès et que vous l’avez sauvé.","en":"Besides, it wasn't so silly to stay there, since you passed by and saved it.","pt":"De resto, não foi assim tão tolo ter ficado lá, já que vocês passaram ao pé e o salvaram.","es":"Además, no ha sido tan tonto al quedarse allí, puesto que vosotros pasasteis cerca y lo salvasteis."}],"who":{"fr":"Madame de réan","en":"Madame de Réan","pt":"a senhora de Réan","es":"La señora de Réan"}},{"poem":false,"s":[{"fr":"Quant à cela, ma tante, il ne pouvait pas deviner que nous passerions par là.","en":"As for that, Aunt, it couldn't have guessed that we'd come that way.","pt":"Quanto a isso, tia, ele não podia adivinhar que íamos passar por ali.","es":"En cuanto a eso, tía, él no podía adivinar que pasaríamos por allí."}],"who":{"fr":"Paul","en":"Paul","pt":"Paul","es":"Paul"}},{"poem":false,"s":[{"fr":"Lui, non ; mais le bon Dieu, qui le savait, l’a permis afin de vous donner l’occasion d’être charitables, même pour un animal. »","en":"It couldn't, no; but God, who knew, allowed it so as to give you the chance to be charitable, even to an animal.\"","pt":"Ele não; mas Deus, que sabia, permitiu-o para vos dar ocasião de serem caridosos, mesmo com um animal.","es":"Él no; pero Dios, que lo sabía, lo permitió para daros ocasión de ser caritativos, aunque sea con un animal»."}],"who":{"fr":"Madame de réan","en":"Madame de Réan","pt":"a senhora de Réan","es":"La señora de Réan"}},{"poem":false,"s":[{"fr":"Sophie et Paul, qui étaient impatients de revoir leur chat, ne dirent plus rien et retournèrent à la cuisine, où ils trouvèrent Beau-Minon profondément endormi sur la cendre chaude.","en":"Sophie and Paul, who were impatient to see their cat again, said no more and went back to the kitchen, where they found Beau-Minon fast asleep on the warm ashes.","pt":"A Sophie e o Paul, impacientes por voltar a ver o seu gato, não disseram mais nada e voltaram para a cozinha, onde encontraram o Beau-Minon a dormir profundamente na cinza quente.","es":"Sophie y Paul, que estaban impacientes por volver a ver a su gato, no dijeron nada más y volvieron a la cocina, donde encontraron a Bello Minino profundamente dormido sobre la ceniza caliente."},{"fr":"Le cuisinier avait mis près de lui une petite jatte de lait ; il n’y avait donc rien à faire pour lui, et les enfants allèrent jouer dans leur petit jardin.","en":"The cook had put a little bowl of milk beside him, so there was nothing to do for him, and the children went to play in their little garden.","pt":"O cozinheiro tinha-lhe posto ao pé uma tigelinha de leite; não havia, portanto, nada a fazer por ele, e as crianças foram brincar para o seu jardinzinho.","es":"El cocinero le había puesto al lado un cuenquito de leche; así que no había nada que hacer por él, y los niños se fueron a jugar a su jardincito."}]},{"poem":false,"s":[{"fr":"Beau-Minon ne mourut pas ; en peu de jours il redevint fort, bien portant et gai.","en":"Beau-Minon didn't die; in a few days he was strong, healthy and cheerful again.","pt":"O Beau-Minon não morreu; em poucos dias voltou a ficar forte, saudável e alegre.","es":"Bello Minino no se murió; en pocos días volvió a estar fuerte, sano y alegre."},{"fr":"À mesure qu’il grandissait, il devenait plus beau ; ses longs poils blancs étaient doux et soyeux ; ses grands yeux noirs étaient brillants comme des soleils ; son nez rose lui donnait un petit air gentil et enfantin.","en":"As he grew, he became more beautiful; his long white fur was soft and silky; his big black eyes were as bright as suns; his pink nose gave him a sweet, childlike look.","pt":"À medida que crescia, ficava mais bonito; o seu pelo branco e comprido era macio e sedoso; os grandes olhos pretos brilhavam como sóis; o nariz cor-de-rosa dava-lhe um arzinho gentil e infantil.","es":"A medida que crecía, se volvía más bonito; su largo pelo blanco era suave y sedoso; sus grandes ojos negros brillaban como soles; su nariz rosada le daba un aire gracioso e infantil."},{"fr":"C’était un vrai chat angora de la plus belle espèce.","en":"He was a real Angora cat of the finest kind.","pt":"Era um verdadeiro gato angorá da raça mais bonita.","es":"Era un verdadero gato de angora de la raza más hermosa."},{"fr":"Sophie l’aimait beaucoup ; Paul, qui venait très souvent passer quelques jours avec Sophie, l’aimait bien aussi.","en":"Sophie loved him very much; Paul, who very often came to spend a few days with Sophie, loved him too.","pt":"A Sophie gostava muito dele; o Paul, que vinha muitas vezes passar uns dias com a Sophie, também gostava muito dele.","es":"Sophie lo quería mucho; Paul, que venía muy a menudo a pasar unos días con Sophie, también lo quería mucho."},{"fr":"Beau-Minon était le plus heureux des chats.","en":"Beau-Minon was the happiest of cats.","pt":"O Beau-Minon era o mais feliz dos gatos.","es":"Bello Minino era el más feliz de los gatos."},{"fr":"Il avait un seul défaut, qui désolait Sophie : il était cruel pour les oiseaux.","en":"He had only one fault, which grieved Sophie: he was cruel to birds.","pt":"Tinha um único defeito, que desolava a Sophie: era cruel com os pássaros.","es":"Solo tenía un defecto, que desesperaba a Sophie: era cruel con los pájaros."},{"fr":"Aussitôt qu’il était dehors, il grimpait aux arbres pour chercher des nids et pour manger les petits qu’il y trouvait.","en":"As soon as he was outside, he climbed the trees looking for nests and ate the babies he found in them.","pt":"Mal estava lá fora, trepava às árvores à procura de ninhos e para comer os filhotes que lá encontrava.","es":"En cuanto estaba fuera, trepaba a los árboles para buscar nidos y comerse a los pajaritos que encontraba en ellos."},{"fr":"Quelquefois même il avait mangé les pauvres mamans oiseaux qui cherchaient à défendre leurs petits contre le méchant Beau-Minon.","en":"Sometimes he had even eaten the poor mother birds who tried to defend their babies against wicked Beau-Minon.","pt":"Às vezes até tinha comido as pobres mães pássaro que tentavam defender os filhos contra o malvado do Beau-Minon.","es":"A veces incluso se había comido a las pobres mamás pájaro que intentaban defender a sus pequeños del malvado Bello Minino."},{"fr":"Quand Sophie et Paul le voyaient grimper aux arbres, ils faisaient ce qu’ils pouvaient pour le faire descendre ; mais Beau-Minon ne les écoutait pas, et continuait tout de même à grimper et à manger les petits oiseaux.","en":"When Sophie and Paul saw him climbing the trees, they did what they could to make him come down; but Beau-Minon wouldn't listen, and kept on climbing and eating the little birds all the same.","pt":"Quando a Sophie e o Paul o viam trepar às árvores, faziam o que podiam para o fazer descer; mas o Beau-Minon não lhes ligava e continuava na mesma a trepar e a comer os passarinhos.","es":"Cuando Sophie y Paul lo veían trepar a los árboles, hacían lo que podían para que bajara; pero Bello Minino no les hacía caso y seguía trepando y comiéndose a los pajaritos."},{"fr":"On entendait alors des cuic, cuic plaintifs.","en":"Then you could hear pitiful little cheeps.","pt":"Ouvia-se então uns piu-piu lastimosos.","es":"Entonces se oían unos «pío, pío» lastimeros."}]},{"poem":false,"s":[{"fr":"Lorsque Beau-Minon descendait de l’arbre, Sophie lui donnait de grands coups de verges : mais il trouva moyen de les éviter en restant si longtemps tout en haut de l’arbre, que Sophie ne pouvait pas l’atteindre.","en":"When Beau-Minon came down from the tree, Sophie gave him hard smacks with a switch; but he found a way to avoid them by staying so long at the top of the tree that Sophie couldn't reach him.","pt":"Quando o Beau-Minon descia da árvore, a Sophie dava-lhe grandes vergastadas: mas ele arranjou maneira de as evitar ficando tanto tempo no alto da árvore que a Sophie não o conseguia alcançar.","es":"Cuando Bello Minino bajaba del árbol, Sophie le daba unos buenos varazos: pero él encontró la manera de evitarlos quedándose tanto rato en lo alto del árbol que Sophie no podía alcanzarlo."},{"fr":"D’autres fois, quand il était arrivé à moitié de l’arbre, il s’élançait, sautait à terre et se sauvait à toutes jambes avant que Sophie eût pu l’attraper.","en":"Other times, when he was halfway down the tree, he would spring off, jump to the ground and run away as fast as he could before Sophie could catch him.","pt":"Outras vezes, quando estava a meio da árvore, lançava-se, saltava para o chão e fugia a sete pés antes que a Sophie o conseguisse apanhar.","es":"Otras veces, cuando había bajado hasta la mitad del árbol, se lanzaba, saltaba al suelo y escapaba a toda velocidad antes de que Sophie pudiera atraparlo."}]},{"poem":false,"s":[{"fr":"« Prends garde, Beau-Minon ! lui disaient les enfants.","en":"\"Watch out, Beau-Minon!\" the children would say to him.","pt":"— Tem cuidado, Beau-Minon! — diziam-lhe as crianças.","es":"«¡Ten cuidado, Bello Minino!», le decían los niños."},{"fr":"Le bon Dieu te punira de ta méchanceté.","en":"\"God will punish you for your wickedness.","pt":"— Deus vai castigar-te pela tua maldade.","es":"«Dios te castigará por tu maldad."},{"fr":"Il t’arrivera malheur un jour. »","en":"Something bad will happen to you one day.\"","pt":"Um dia vai acontecer-te uma desgraça.","es":"Algún día te pasará una desgracia»."}]},{"poem":false,"s":[{"fr":"Beau-Minon ne les écoutait pas.","en":"Beau-Minon didn't listen to them.","pt":"O Beau-Minon não lhes dava ouvidos.","es":"Bello Minino no les hacía caso."}]},{"poem":false,"s":[{"fr":"Un jour Mme de Réan apporta dans le salon un charmant oiseau, dans une belle cage toute dorée.","en":"One day Madame de Réan brought into the drawing room a charming bird in a beautiful gilded cage.","pt":"Um dia, a senhora de Réan trouxe para a sala um pássaro encantador, numa linda gaiola toda dourada.","es":"Un día, la señora de Réan trajo al salón un pájaro precioso en una bonita jaula toda dorada."}]},{"poem":false,"s":[{"fr":"« Voyez, mes enfants, quel joli bouvreuil m’a envoyé un de mes amis.","en":"\"Look, children, what a pretty bullfinch one of my friends has sent me.","pt":"— Vejam, meninos, que dom-fafe tão bonito me mandou um amigo meu.","es":"«Mirad, niños, qué camachuelo tan bonito me ha mandado un amigo."},{"fr":"Il chante parfaitement.","en":"It sings perfectly.","pt":"Canta na perfeição.","es":"Canta de maravilla."}]},{"poem":false,"s":[{"fr":"Oh ! que je voudrais l’entendre !","en":"Oh, how I'd love to hear it!","pt":"Oh, como eu gostava de o ouvir!","es":"¡Oh, cuánto me gustaría oírlo!"}],"who":{"fr":"Sophie et paul, ensemble","en":"Sophie and Paul, together","pt":"Sophie e Paul, ao mesmo tempo","es":"Sophie y Paul, a la vez"}},{"poem":false,"s":[{"fr":"Je vais le faire chanter ; mais n’approchez pas trop, pour ne pas l’effrayer…","en":"I'll make it sing; but don't come too close, or you'll frighten it…","pt":"Vou pô-lo a cantar; mas não se aproximem demasiado, para não o assustarem…","es":"Voy a hacerle cantar; pero no os acerquéis demasiado, para no asustarlo…"},{"fr":"Petit, petit, continua Mme de Réan en parlant au bouvreuil, chante, mon ami ; chante, petit, chante. »","en":"Little one, little one,\" Madame de Réan went on, talking to the bullfinch, \"sing, my friend; sing, little one, sing.\"","pt":"Pequenino, pequenino — continuou a senhora de Réan, falando para o dom-fafe —, canta, meu amigo; canta, pequenino, canta.","es":"Pequeño, pequeño», siguió la señora de Réan hablándole al camachuelo, «canta, amigo mío; canta, pequeño, canta»."}],"who":{"fr":"Madame de réan","en":"Madame de Réan","pt":"a senhora de Réan","es":"La señora de Réan"}},{"poem":false,"s":[{"fr":"Le bouvreuil commença à se balancer, à pencher sa tête à droite et à gauche, et puis il se mit à siffler l’air : Au clair de la lune.","en":"The bullfinch began to sway and tilt its head left and right, and then it started whistling the tune 'Au clair de la lune'.","pt":"O dom-fafe começou a baloiçar-se, a inclinar a cabeça para a direita e para a esquerda, e depois pôs-se a assobiar a música «Au clair de la lune».","es":"El camachuelo empezó a balancearse, a inclinar la cabeza a derecha e izquierda, y luego se puso a silbar la canción «Au clair de la lune»."},{"fr":"Quand il eut fini, il siffla : J’ai du bon tabac, puis : Le bon roi Dagobert.","en":"When it had finished, it whistled 'J'ai du bon tabac', then 'Le bon roi Dagobert'.","pt":"Quando acabou, assobiou «J'ai du bon tabac», e depois «Le bon roi Dagobert».","es":"Cuando terminó, silbó «J'ai du bon tabac», y luego «Le bon roi Dagobert»."}]},{"poem":false,"s":[{"fr":"Les enfants l’écoutaient sans bouger ; ils osaient à peine respirer, pour ne pas faire peur au bouvreuil.","en":"The children listened without moving; they hardly dared to breathe, so as not to frighten the bullfinch.","pt":"As crianças ouviam-no sem se mexer; mal se atreviam a respirar, para não assustar o dom-fafe.","es":"Los niños lo escuchaban sin moverse; apenas se atrevían a respirar, para no asustar al camachuelo."},{"fr":"Quand il eut fini, Paul s’écria :","en":"When it had finished, Paul cried:","pt":"Quando ele acabou, o Paul exclamou:","es":"Cuando terminó, Paul exclamó:"}]},{"poem":false,"s":[{"fr":"« Oh ! ma tante, comme il chante bien !","en":"\"Oh, Aunt, how well it sings!","pt":"— Oh, tia, como ele canta bem!","es":"«¡Oh, tía, qué bien canta!"},{"fr":"Quelle petite voix douce !","en":"What a sweet little voice!","pt":"Que vozinha tão doce!","es":"¡Qué vocecita tan dulce!"},{"fr":"Je voudrais l’entendre toujours !","en":"I'd like to listen to it forever!\"","pt":"Queria ouvi-lo sempre!","es":"¡Me gustaría oírlo siempre!"}]},{"poem":false,"s":[{"fr":"— Nous le ferons recommencer après dîner, dit Mme de Réan ; à présent il est fatigué, il arrive de voyage ; donnons-lui à manger.","en":"\"We'll make it sing again after dinner,\" said Madame de Réan; \"it's tired now, it's just arrived from a journey; let's feed it.","pt":"— Vamos pô-lo a cantar outra vez depois do jantar — disse a senhora de Réan —; agora está cansado, acabou de chegar de viagem; vamos dar-lhe de comer.","es":"—Le haremos cantar otra vez después de cenar», dijo la señora de Réan; «ahora está cansado, acaba de llegar de viaje; démosle de comer."},{"fr":"Allez au jardin, mes enfants, rapportez-moi du mouron et du plantain ; le jardinier vous montrera où il y en a. »","en":"Go into the garden, children, and bring me some chickweed and plantain; the gardener will show you where there is some.\"","pt":"Vão ao jardim, meninos, e tragam-me morugem e tanchagem; o jardineiro mostra-vos onde há.","es":"Id al jardín, niños, y traedme pamplina y llantén; el jardinero os enseñará dónde hay»."}]},{"poem":false,"s":[{"fr":"Les enfants coururent au potager et rapportèrent une telle quantité de mouron qu’on aurait pu y enterrer toute la cage.","en":"The children ran to the vegetable garden and brought back so much chickweed that you could have buried the whole cage in it.","pt":"As crianças correram para a horta e trouxeram tanta morugem que dava para enterrar a gaiola toda.","es":"Los niños corrieron a la huerta y trajeron tal cantidad de pamplina que se podría haber enterrado toda la jaula en ella."},{"fr":"Leur maman leur dit de n’en cueillir qu’une petite poignée une autre fois, et ils en mirent dans la cage du bouvreuil, qui commença tout de suite à le becqueter.","en":"Their mother told them to pick only a small handful another time, and they put some in the bullfinch's cage, and it began pecking at it straight away.","pt":"A mãe disse-lhes que de outra vez só apanhassem uma mão-cheia, e eles puseram um pouco na gaiola do dom-fafe, que começou logo a debicar.","es":"Su mamá les dijo que otra vez solo cogieran un puñadito, y metieron un poco en la jaula del camachuelo, que empezó enseguida a picotearla."}]},{"poem":false,"s":[{"fr":"« Allons dîner à présent, mes enfants, dit Mme de Réan, vos papas nous attendent. »","en":"\"Let's go and have dinner now, children,\" said Madame de Réan; \"your papas are waiting for us.\"","pt":"— Agora vamos jantar, meninos — disse a senhora de Réan —; os vossos papás estão à nossa espera.","es":"«Vamos a cenar ahora, niños», dijo la señora de Réan; «vuestros papás nos esperan»."}]},{"poem":false,"s":[{"fr":"Pendant le dîner, on parla beaucoup du joli bouvreuil.","en":"During dinner they talked a lot about the pretty bullfinch.","pt":"Durante o jantar, falou-se muito do lindo dom-fafe.","es":"Durante la cena se habló mucho del bonito camachuelo."}]},{"poem":false,"s":[{"fr":"« Quelle belle tête noire il a ! dit Sophie.","en":"\"What a beautiful black head it has!\" said Sophie.","pt":"— Que cabeça preta tão bonita ele tem! — disse a Sophie.","es":"«¡Qué cabeza negra tan bonita tiene!», dijo Sophie."}]},{"poem":false,"s":[{"fr":"— Et quel joli ventre rouge ! dit Paul.","en":"\"And what a pretty red breast!\" said Paul.","pt":"— E que barriga vermelha tão linda! — disse o Paul.","es":"«¡Y qué barriga roja tan bonita!», dijo Paul."}]},{"poem":false,"s":[{"fr":"— Et comme il chante bien ! dit Mme de Réan.","en":"\"And how well it sings!\" said Madame de Réan.","pt":"— E como canta bem! — disse a senhora de Réan.","es":"«¡Y qué bien canta!», dijo la señora de Réan."}]},{"poem":false,"s":[{"fr":"— Il faudra lui faire chanter tous ses airs », dit M. de Réan.","en":"\"We'll have to make it sing all its tunes,\" said Monsieur de Réan.","pt":"— Vamos ter de o pôr a cantar todas as músicas que sabe — disse o senhor de Réan.","es":"«Habrá que hacerle cantar todas sus canciones», dijo el señor de Réan."}]},{"poem":false,"s":[{"fr":"Aussitôt que le dîner fut fini, on retourna au salon ; les enfants couraient en avant.","en":"As soon as dinner was over, they went back to the drawing room; the children ran on ahead.","pt":"Assim que o jantar acabou, voltaram para a sala; as crianças corriam à frente.","es":"En cuanto terminó la cena, volvieron al salón; los niños corrían delante."},{"fr":"Au moment d’entrer au salon, Mme de Réan y entendit pousser un cri affreux ; elle accourut et les trouva immobiles de frayeur et montrant du doigt la cage du bouvreuil.","en":"Just as she was going into the drawing room, Madame de Réan heard a dreadful scream; she rushed in and found the children frozen with fright, pointing at the bullfinch's cage.","pt":"No momento de entrar na sala, a senhora de Réan ouviu lá dentro um grito horrível; acorreu e encontrou-as imóveis de medo, a apontar com o dedo para a gaiola do dom-fafe.","es":"En el momento de entrar en el salón, la señora de Réan oyó allí un grito espantoso; acudió corriendo y los encontró inmóviles de susto, señalando con el dedo la jaula del camachuelo."},{"fr":"De cette cage, dont plusieurs barreaux étaient tordus et cassés, Beau-Minon s’élançait par terre, tenant dans sa gueule le pauvre bouvreuil qui battait encore des ailes.","en":"From that cage, several of whose bars were twisted and broken, Beau-Minon was leaping to the floor, holding in his mouth the poor bullfinch, which was still flapping its wings.","pt":"Daquela gaiola, com várias grades tortas e partidas, o Beau-Minon saltava para o chão, levando na boca o pobre dom-fafe, que ainda batia as asas.","es":"De aquella jaula, que tenía varios barrotes torcidos y rotos, Bello Minino saltaba al suelo, llevando en la boca al pobre camachuelo, que todavía batía las alas."},{"fr":"Mme de Réan cria à son tour et courut à Beau-Minon pour lui faire lâcher l’oiseau.","en":"Madame de Réan screamed in her turn and ran at Beau-Minon to make him drop the bird.","pt":"A senhora de Réan gritou por sua vez e correu para o Beau-Minon para o obrigar a largar o pássaro.","es":"La señora de Réan gritó a su vez y corrió hacia Bello Minino para hacerle soltar el pájaro."},{"fr":"Beau-Minon se sauva sous un fauteuil.","en":"Beau-Minon escaped under an armchair.","pt":"O Beau-Minon fugiu para debaixo de uma poltrona.","es":"Bello Minino se escapó debajo de un sillón."},{"fr":"M. de Réan, qui entrait en ce moment, saisit une pincette et voulut en donner un coup à Beau-Minon.","en":"Monsieur de Réan, who came in at that moment, grabbed a pair of tongs and tried to hit Beau-Minon with them.","pt":"O senhor de Réan, que entrava nesse momento, pegou numa tenaz e quis dar com ela no Beau-Minon.","es":"El señor de Réan, que entraba en ese momento, cogió unas tenazas de la chimenea y quiso darle un golpe a Bello Minino."},{"fr":"Mais le chat, qui était prêt à se sauver, s’élança vers la porte restée entr’ouverte.","en":"But the cat, ready to run, shot towards the door, which had been left half open.","pt":"Mas o gato, pronto a fugir, lançou-se para a porta, que tinha ficado entreaberta.","es":"Pero el gato, que estaba listo para escapar, se lanzó hacia la puerta, que se había quedado entreabierta."},{"fr":"M. de Réan le poursuivit de chambre en chambre, de corridor en corridor.","en":"Monsieur de Réan chased him from room to room, from corridor to corridor.","pt":"O senhor de Réan perseguiu-o de quarto em quarto, de corredor em corredor.","es":"El señor de Réan lo persiguió de habitación en habitación y de pasillo en pasillo."},{"fr":"Le pauvre oiseau ne criait plus, ne se débattait plus.","en":"The poor bird was no longer crying or struggling.","pt":"O pobre pássaro já não gritava, já não se debatia.","es":"El pobre pájaro ya no piaba ni forcejeaba."},{"fr":"Enfin M. de Réan parvint à attraper Beau-Minon avec la pincette.","en":"At last Monsieur de Réan managed to catch Beau-Minon with the tongs.","pt":"Por fim, o senhor de Réan conseguiu apanhar o Beau-Minon com a tenaz.","es":"Por fin, el señor de Réan consiguió alcanzar a Bello Minino con las tenazas."},{"fr":"Le coup avait été si fort que sa gueule s’ouvrit et laissa échapper l’oiseau.","en":"The blow was so hard that his mouth opened and let the bird fall.","pt":"A pancada foi tão forte que ele abriu a boca e deixou escapar o pássaro.","es":"El golpe fue tan fuerte que se le abrió la boca y soltó el pájaro."},{"fr":"Pendant que le bouvreuil tombait d’un côté, Beau-Minon tombait de l’autre.","en":"While the bullfinch fell one way, Beau-Minon fell the other.","pt":"Enquanto o dom-fafe caía para um lado, o Beau-Minon caía para o outro.","es":"Mientras el camachuelo caía por un lado, Bello Minino caía por el otro."},{"fr":"Il eut deux ou trois convulsions et il ne bougea plus ; la pincette l’avait frappé à la tête ; il était mort.","en":"He twitched two or three times and then didn't move again; the tongs had hit him on the head; he was dead.","pt":"Teve duas ou três convulsões e não voltou a mexer-se; a tenaz tinha-lhe acertado na cabeça; estava morto.","es":"Tuvo dos o tres convulsiones y ya no se movió; las tenazas le habían dado en la cabeza; estaba muerto."}]},{"poem":false,"s":[{"fr":"Mme de Réan et les enfants, qui couraient après M. de Réan, après le chat et après le bouvreuil, arrivèrent au moment de la dernière convulsion de Beau-Minon.","en":"Madame de Réan and the children, who were running after Monsieur de Réan, the cat and the bullfinch, arrived just as Beau-Minon gave his last twitch.","pt":"A senhora de Réan e as crianças, que corriam atrás do senhor de Réan, do gato e do dom-fafe, chegaram no momento da última convulsão do Beau-Minon.","es":"La señora de Réan y los niños, que corrían detrás del señor de Réan, del gato y del camachuelo, llegaron en el momento de la última convulsión de Bello Minino."}]},{"poem":false,"s":[{"fr":"« Beau-Minon, mon pauvre Beau-Minon ! s’écria Sophie.","en":"\"Beau-Minon, my poor Beau-Minon!\" cried Sophie.","pt":"— Beau-Minon, meu pobre Beau-Minon! — exclamou a Sophie.","es":"«¡Bello Minino, mi pobre Bello Minino!», exclamó Sophie."}]},{"poem":false,"s":[{"fr":"— Le bouvreuil, le pauvre bouvreuil ! s’écria Paul.","en":"\"The bullfinch, the poor bullfinch!\" cried Paul.","pt":"— O dom-fafe, o pobre dom-fafe! — exclamou o Paul.","es":"«¡El camachuelo, el pobre camachuelo!», exclamó Paul."}]},{"poem":false,"s":[{"fr":"— Mon ami, qu’avez-vous fait ? s’écria Mme de Réan.","en":"\"My dear, what have you done?\" cried Madame de Réan.","pt":"— Meu amigo, que fizeste? — exclamou a senhora de Réan.","es":"«¿Qué ha hecho usted, querido?», exclamó la señora de Réan."}]},{"poem":false,"s":[{"fr":"— J’ai puni le coupable, mais je n’ai pu sauver l’innocent, répondit M. de Réan.","en":"\"I punished the guilty one, but I couldn't save the innocent one,\" answered Monsieur de Réan.","pt":"— Castiguei o culpado, mas não consegui salvar o inocente — respondeu o senhor de Réan.","es":"«He castigado al culpable, pero no he podido salvar al inocente», respondió el señor de Réan."},{"fr":"Le bouvreuil est mort étouffé par le méchant Beau-Minon, qui ne tuera plus personne, puisque je l’ai tué sans le vouloir. »","en":"\"The bullfinch has been smothered by wicked Beau-Minon, who won't kill anyone else, since I killed him without meaning to.\"","pt":"— O dom-fafe morreu sufocado pelo malvado do Beau-Minon, que já não vai matar mais ninguém, porque eu o matei sem querer.","es":"«El camachuelo ha muerto asfixiado por el malvado Bello Minino, que ya no matará a nadie más, porque lo he matado sin querer»."}]},{"poem":false,"s":[{"fr":"Sophie n’osait rien dire, mais elle pleura amèrement son pauvre chat, qu’elle aimait malgré ses défauts.","en":"Sophie didn't dare say anything, but she cried bitterly for her poor cat, whom she loved in spite of his faults.","pt":"A Sophie não se atrevia a dizer nada, mas chorou amargamente o seu pobre gato, de quem gostava apesar dos seus defeitos.","es":"Sophie no se atrevía a decir nada, pero lloró amargamente por su pobre gato, al que quería a pesar de sus defectos."}]},{"poem":false,"s":[{"fr":"« Je lui avais bien dit, disait-elle à Paul, que le bon Dieu le punirait de sa méchanceté pour les oiseaux.","en":"\"I told him,\" she said to Paul, \"that God would punish him for being cruel to birds.","pt":"— Bem lhe tinha dito — dizia ela ao Paul — que Deus o havia de castigar pela sua maldade com os pássaros.","es":"«Ya le había dicho yo», le decía a Paul, «que Dios lo castigaría por su maldad con los pájaros."},{"fr":"Hélas ! pauvre Beau-Minon ! te voilà mort, et par ta faute ! »","en":"Alas! Poor Beau-Minon! Now you're dead, and it's your own fault!\"","pt":"Ai, pobre Beau-Minon! Aqui estás tu morto, e por tua culpa!","es":"¡Ay, pobre Bello Minino! ¡Aquí estás muerto, y por tu culpa!»."}]}]});
